const BASE=new URL('./hub-resources.mjs',import.meta.url).href,MANIFEST_SHA='4b7a4316a626b4c44748d351cea96b2fbfe009da59dfa2ec4f3cf2122b756d94';
const digest=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
export async function loadHubResources(){const bitmaps=[],items={};let disposed=false;try{const r=await fetch(new URL('./HUB_RESOURCE_PINS.json',BASE));if(!r.ok)throw Error('HUB_MANIFEST_MISSING');const bytes=await r.arrayBuffer();if(await digest(bytes)!==MANIFEST_SHA)throw Error('HUB_MANIFEST_PIN');const pins=JSON.parse(new TextDecoder().decode(bytes));for(const[k,p]of Object.entries(pins)){const r=await fetch(new URL(p.url,BASE));if(!r.ok)throw Error('HUB_RESOURCE_MISSING');const b=await r.arrayBuffer();if(await digest(b)!==p.sha256)throw Error('HUB_RESOURCE_PIN');items[k]=k.endsWith('.png')?await createImageBitmap(new Blob([b])):k.endsWith('.json')?JSON.parse(new TextDecoder().decode(b)):b;if(k.endsWith('.png'))bitmaps.push(items[k])}const pixels=im=>{const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const g=c.getContext('2d');g.drawImage(im,0,0);return g.getImageData(0,0,c.width,c.height).data},floors={},sources={};for(const state of['OPEN','CLOSED']){const f=pixels(items['floor_'+state.toLowerCase()+'.png']);floors[state]=Uint8Array.from({length:3656*1792},(_,i)=>f[i*4]>127?1:0);sources[state]=pixels(items['source_'+state.toLowerCase()+'.png'])}const render=createEnvironment({sources,manifest:items['lighting/MANIFEST.json'],indices:new Uint32Array(items['lighting/indices.u32']),transmission:new Float64Array(items['lighting/transmission.f64'])});return{items,get pinsVerified(){return!disposed},render,safe([x,y],state){const m=floors[state];if(disposed||!m||!Number.isInteger(x)||!Number.isInteger(y)||x<24||y<18||x+24>=3656||y+18>=1792)return false;for(let yy=y-18;yy<=y+18;yy++)for(let xx=x-24;xx<=x+24;xx++)if(!m[yy*3656+xx])return false;return true},dispose(){if(disposed)return;disposed=true;let first;for(const b of bitmaps)try{b.close?.()}catch(e){first??=e}bitmaps.length=0;if(first)throw first}}}catch(e){for(const b of bitmaps)try{b.close?.()}catch{}bitmaps.length=0;throw e}}
